/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_processingDocumentList", fn: function(){ return ((String(((dma_pageContext.get("processingDocumentList") ?? "")) == null ? '' : ((dma_pageContext.get("processingDocumentList") ?? ""))).length === 0)); } }, { id: "if_corpUsrTpCd", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") === '62' || $c.session.getUserInfo("corpUsrTpCd") === '63'); } }, { id: "if_disclsTitle_txt", fn: function(){ return ((dlt_processingDocumentList.getCellData(0, "disclsTitle") ?? (() => { throw new Error("unresolved:" + "processingDocument.disclsTitle"); })()) !== ''); } }, { id: "c_when_87", fn: function(){ return ((dlt_processingDocumentList.getCellData(0, "langTpCd") ?? (() => { throw new Error("unresolved:" + "processingDocument.langTpCd"); })()) === '1'); } }, { id: "c_otherwise_90", fn: function(){ return (!(((dlt_processingDocumentList.getCellData(0, "langTpCd") ?? (() => { throw new Error("unresolved:" + "processingDocument.langTpCd"); })()) === '1'))); } }, { id: "if_disclsTitle_2_txt", fn: function(){ return ((dlt_processingDocumentList.getCellData(0, "disclsTitle") ?? (() => { throw new Error("unresolved:" + "processingDocument.disclsTitle"); })()) !== ''); } }, { id: "c_when_97_txt", fn: function(){ return ((dlt_processingDocumentList.getCellData(0, "disclsProcsStatCd") ?? (() => { throw new Error("unresolved:" + "processingDocument.disclsProcsStatCd"); })()) === '00' || (dlt_processingDocumentList.getCellData(0, "disclsProcsStatCd") ?? (() => { throw new Error("unresolved:" + "processingDocument.disclsProcsStatCd"); })()) === '01'); } }, { id: "c_when_98_txt", fn: function(){ return ((dlt_processingDocumentList.getCellData(0, "disclsProcsStatCd") ?? (() => { throw new Error("unresolved:" + "processingDocument.disclsProcsStatCd"); })()) === '10' || (dlt_processingDocumentList.getCellData(0, "disclsProcsStatCd") ?? (() => { throw new Error("unresolved:" + "processingDocument.disclsProcsStatCd"); })()) === '20'); } }, { id: "if_corpUsrTpCd_2", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") === '62' || $c.session.getUserInfo("corpUsrTpCd") === '63'); } }, { id: "c_when_104_txt", fn: function(){ return ((dlt_processingDocumentList.getCellData(0, "disclsProcsStatCd") ?? (() => { throw new Error("unresolved:" + "processingDocument.disclsProcsStatCd"); })()) === '00' || (dlt_processingDocumentList.getCellData(0, "disclsProcsStatCd") ?? (() => { throw new Error("unresolved:" + "processingDocument.disclsProcsStatCd"); })()) === '01'); } }, { id: "c_when_105_txt", fn: function(){ return ((dlt_processingDocumentList.getCellData(0, "disclsProcsStatCd") ?? (() => { throw new Error("unresolved:" + "processingDocument.disclsProcsStatCd"); })()) === '10' || (dlt_processingDocumentList.getCellData(0, "disclsProcsStatCd") ?? (() => { throw new Error("unresolved:" + "processingDocument.disclsProcsStatCd"); })()) === '20'); } }, { id: "if_corpUsrTpCd_3", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") !== '62' && $c.session.getUserInfo("corpUsrTpCd") !== '63'); } }, { id: "if_occsnlDisclsSchedules", fn: function(){ return ((String(((dma_pageContext.get("occsnlDisclsSchedules") ?? "")) == null ? '' : ((dma_pageContext.get("occsnlDisclsSchedules") ?? ""))).length === 0)); } }, { id: "if_writingDocumentList", fn: function(){ return ((String(((dma_pageContext.get("writingDocumentList") ?? "")) == null ? '' : ((dma_pageContext.get("writingDocumentList") ?? ""))).length === 0)); } }, { id: "if_befDocTpCd", fn: function(){ return ((dma_pageContext.get("befDocTpCd") ?? "") !== (dlt_docDisclosureDocument.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtrptMaindocTpCd"); })())); } }, { id: "if_befDocTpCd", fn: function(){ return ((dma_pageContext.get("isFirst") ?? "") !== 'true'); } }, { id: "btn_goWrite", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'F'); } }, { id: "btn_goViewer_2", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'M'); } }, { id: "btn_goViewer_3", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'A'); } }, { id: "c_when_138", fn: function(){ return ((dlt_docDisclosureDocument.getCellData(0, "docNo") ?? (() => { throw new Error("unresolved:" + "subdoc.docNo"); })()) === '00000000000000'); } }, { id: "c_otherwise_146", fn: function(){ return (!(((dlt_docDisclosureDocument.getCellData(0, "docNo") ?? (() => { throw new Error("unresolved:" + "subdoc.docNo"); })()) === '00000000000000'))); } }, { id: "if_disclsTitle_3_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsTitle"); })() !== ''); } }, { id: "if_wrtrptMaindocTpCd", fn: function(){ return ((dlt_docDisclosureDocument.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtrptMaindocTpCd"); })()) === '1'); } }, { id: "c_otherwise_155", fn: function(){ return (!(((dlt_docDisclosureDocument.getCellData(0, "wrtYn") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtYn"); })()) === 'Y'))); } }, { id: "if_wrtrptMaindocTpCd_2", fn: function(){ return ((dlt_docDisclosureDocument.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtrptMaindocTpCd"); })()) === '2'); } }, { id: "c_when_160_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'F'); } }, { id: "c_when_161_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'M'); } }, { id: "c_when_162_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'U'); } }, { id: "c_when_163_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'A'); } }, { id: "if_wrtrptMaindocTpCd_3", fn: function(){ return ((dlt_docDisclosureDocument.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtrptMaindocTpCd"); })()) === '1'); } }, { id: "if_corpUsrTpCd_4", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") !== '62' && $c.session.getUserInfo("corpUsrTpCd") !== '63'); } }, { id: "if_wrtrptMaindocTpCd_4", fn: function(){ return ((dlt_docDisclosureDocument.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtrptMaindocTpCd"); })()) === '1'); } }, { id: "btn_goWrite_3", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'F'); } }, { id: "btn_goViewer_4", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'M'); } }, { id: "btn_goViewer_5", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'A'); } }, { id: "c_when_171", fn: function(){ return ((dlt_docDisclosureDocument.getCellData(0, "docNo") ?? (() => { throw new Error("unresolved:" + "subdoc.docNo"); })()) === '00000000000000'); } }, { id: "c_otherwise_179", fn: function(){ return (!(((dlt_docDisclosureDocument.getCellData(0, "docNo") ?? (() => { throw new Error("unresolved:" + "subdoc.docNo"); })()) === '00000000000000'))); } }, { id: "if_disclsTitle_4_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsTitle"); })() !== ''); } }, { id: "if_wrtrptMaindocTpCd_5", fn: function(){ return ((dlt_docDisclosureDocument.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtrptMaindocTpCd"); })()) === '1'); } }, { id: "c_otherwise_188", fn: function(){ return (!(((dlt_docDisclosureDocument.getCellData(0, "wrtYn") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtYn"); })()) === 'Y'))); } }, { id: "if_wrtrptMaindocTpCd_6", fn: function(){ return ((dlt_docDisclosureDocument.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtrptMaindocTpCd"); })()) === '2'); } }, { id: "c_when_194_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'F'); } }, { id: "c_when_195_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'M'); } }, { id: "c_when_196_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'U'); } }, { id: "c_when_197_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'A'); } }, { id: "if_wrtrptMaindocTpCd_7", fn: function(){ return ((dlt_docDisclosureDocument.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtrptMaindocTpCd"); })()) === '1'); } }, { id: "if_corpUsrTpCd_5", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") === '62' || $c.session.getUserInfo("corpUsrTpCd") === '63'); } }, { id: "if_submittedDocumentList", fn: function(){ return ((String(((dma_pageContext.get("submittedDocumentList") ?? "")) == null ? '' : ((dma_pageContext.get("submittedDocumentList") ?? ""))).length === 0)); } }, { id: "c_otherwise_215", fn: function(){ return (!(((() => { throw new Error("unresolved:data:" + "doc.listFormYn"); })() === 'Y'))); } }, { id: "if_corpUsrTpCd_6", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") === '62' || $c.session.getUserInfo("corpUsrTpCd") === '63'); } }, { id: "if_disclsTitle_5_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsTitle"); })() !== ''); } }, { id: "c_when_222", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.langTpCd"); })() === '0'); } }, { id: "c_otherwise_225", fn: function(){ return (!(((() => { throw new Error("unresolved:data:" + "doc.langTpCd"); })() === '0'))); } }, { id: "if_disclsTitle_6_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsTitle"); })() !== ''); } }, { id: "c_otherwise_253", fn: function(){ return (!(((String(((dma_pageContext.get("inquiredDisclosureList") ?? "")) == null ? '' : ((dma_pageContext.get("inquiredDisclosureList") ?? ""))).length === 0)))); } }, { id: "if_corpUsrTpCd_9", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") === '1A'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_83", entity: "dlt_processingDocumentList", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return "- (영문)" + String(v("formKorNm")); } }, { childId: "__rc1", fn: function (v, i) { return "(" + String(v("disclsTitle")) + ")"; } }, { childId: "__rc2", fn: function (v, i) { return "- " + String(v("formKorNm")); } }, { childId: "__rc3", fn: function (v, i) { return "(" + String(v("disclsTitle")) + ")"; } }, { childId: "__rc4", fn: function (v, i) { return String(v("tgtComNm")); } }, { childId: "__rc5", fn: function (v, i) { return String(dlt_writingDocumentList.getCellData(0, "disclsProcsDdTm")); } }, { childId: "__rc6", fn: function (v, i) { return String(dlt_writingDocumentList.getCellData(0, "disclsProcsDdTm")); } }] },
        { genId: "c_foreach_115", entity: "dlt_occsnlDisclsSchedules", countIds: [], cells: [{ childId: "btn_ScheduleManagement", fn: function (v, i) { return String(v("schdlTitle")); } }, { childId: "__rc7", fn: function (v, i) { return String(v("schdlContn")); } }, { childId: "__rc8", fn: function (v, i) { return String((String(String(v("calndDd")) == null ? '' : String(v("calndDd"))) === '' ? '' : String("yyyy-MM-dd").replace(/yyyy/g, String(v("calndDd")).slice(0,4)).replace(/MM/g, String(v("calndDd")).slice(4,6)).replace(/dd/g, String(v("calndDd")).slice(6,8)).replace(/HH/g, String(v("calndDd")).slice(8,10)).replace(/mm/g, String(v("calndDd")).slice(10,12)).replace(/ss/g, String(v("calndDd")).slice(12,14)))); } }] },
        { genId: "c_foreach_131", entity: "dlt_docDisclosureDocument", countIds: [], cells: [{ childId: "__rc16", fn: function (v, i) { return " " + String(v("formKorNm")) + "&nbsp; (영문)" + String(v("formKorNm")) + "&nbsp; "; } }, { childId: "__rc17", fn: function (v, i) { return " " + String(v("formKorNm")) + "&nbsp; (영문)" + String(v("formKorNm")) + "&nbsp; "; } }] },
        { genId: "c_foreach_210", entity: "dlt_submittedDocumentList", countIds: [], cells: [{ childId: "__rc18", fn: function (v, i) { return String(v("formKorNm")); } }, { childId: "__rc19", fn: function (v, i) { return "(" + String(v("disclsTitle")) + ")"; } }, { childId: "__rc20", fn: function (v, i) { return "(영문)" + String(v("formKorNm")); } }, { childId: "__rc21", fn: function (v, i) { return "(" + String(v("disclsTitle")) + ")"; } }, { childId: "__rc22", fn: function (v, i) { return String(v("tgtComNm")); } }, { childId: "__rc23", fn: function (v, i) { return String(v("disclsProcsStatNm")); } }, { childId: "__rc24", fn: function (v, i) { return String(v("disclsProcsDdTm")); } }, { childId: "__rc25", fn: function (v, i) { return String(v("disclsAcptTpNm")); } }, { childId: "__rc26", fn: function (v, i) { return String(v("disclsProcsStatNm")); } }, { childId: "__rc27", fn: function (v, i) { return String(v("disclsProcsDdTm")); } }, { childId: "__rc28", fn: function (v, i) { return String(v("disclsAcptTpNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_tgtIsuSrtCd", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["repIsuSrtCd"] ?? ""); } },
        { childId: "ipt_tgtIsuSrtCd_2", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["repIsuSrtCd"] ?? ""); } },
        { childId: "ipt_tgtIsurCd_3", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["isurCd"] ?? ""); } },
        { childId: "ipt_tgtFssUnqNo_3", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["fssUnqNo"] ?? ""); } },
        { childId: "ipt_tgtIsuSrtCd_3", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["repIsuSrtCd"] ?? ""); } },
        { childId: "ipt_tgtComNm_3", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comAbbrv"] ?? ""); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        let param = "";
        let abscissa = 0;
        const tmp = "" + dma_list.get("name") + "";
        for (let i = 0; i < (function(){ throw 'unresolved:list:popupList'; })(); i++) {
            if (scwin.getCookie((String(((function(){ throw 'unresolved:list:popupList'; })()) == null ? '' : ((function(){ throw 'unresolved:list:popupList'; })())).indexOf('$' + '{') >= 0 ? '' : String(((function(){ throw 'unresolved:list:popupList'; })()) == null ? '' : ((function(){ throw 'unresolved:list:popupList'; })())))) !== (String(((function(){ throw 'unresolved:list:popupList'; })()) == null ? '' : ((function(){ throw 'unresolved:list:popupList'; })())).indexOf('$' + '{') >= 0 ? '' : String(((function(){ throw 'unresolved:list:popupList'; })()) == null ? '' : ((function(){ throw 'unresolved:list:popupList'; })())))) {
                if (tmp.substring(0, 4) === 'http') {
                    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
                    $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(tmp), { width: "${popupList[__i].width}", height: "${popupList[__i].height}", scrollbars: false, type: "pageFramePopup" }, {});
