    } else {
        ($c.util.getComponent(divId + '_otherForm') && $c.util.getComponent(divId + '_otherForm').hide ? $c.util.getComponent(divId + '_otherForm').hide() : console.warn('[sdd] hide 대상 미해결: ' + divId + '_otherForm'));
    }
    scwin.otherFormObj = $c.util.getComponent(divId + '_otherForm');
};

/**
 * @method
 * @name precheckBeforeOpenNotice
 * @description precheck Before Open Notice 처리
 * @param {*} fromDate fromDate
 * @param {*} toDate toDate
 * @returns {void}
 * @hidden N
 */
scwin.precheckBeforeOpenNotice = function (fromDate, toDate) {
    const curDate = new Date();
    if (fromDate <= curDate && curDate <= toDate) {
        return true;
    }
    return false;
};

