/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseXML responseXML
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onCompleteResponse = async function (responseXML) {
    if ((responseXML == null) || ('' === responseXML)) {
        await $c.win.alert("데이터를 불러올 수 없습니다.");
    } else {
        const xmlDoc = xmlHttp.responseXML;
        const chkSubstituteInfo = xmlDoc.getElementsByTagName("chkSubstituteInfo")[0];
        let chrgWorkYn = "";
        let chrgNm = "";
        let toDate = "";
        let substituteInfo = "";
        if (chkSubstituteInfo != null) {
            chrgWorkYn = chkSubstituteInfo.getElementsByTagName("result")[0].firstChild.nodeValue;
            chrgNm = chkSubstituteInfo.getElementsByTagName("chrgNm")[0].firstChild.nodeValue;
            toDate = chkSubstituteInfo.getElementsByTagName("toDate")[0].firstChild.nodeValue;
            substituteInfo = chkSubstituteInfo.getElementsByTagName("substituteInfo")[0].firstChild.nodeValue;
        }
        if (chrgWorkYn === 'N') {
            await scwin.substituteInfoPop(chrgNm, toDate, substituteInfo);
        }
    }
};

/**
 * @method
 * @name substituteInfoPop
 * @description substitute Info Pop 처리
 * @param {String} chrgNm chrgNm
 * @param {*} toDate toDate
 * @param {*} substituteInfo substituteInfo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.substituteInfoPop = async function (chrgNm, toDate, substituteInfo) {
    let arrDepNm = [];
    let arrEmpNm = [];
    let arrTelNo = [];
    let tmpArr = [];
    const arrSubstitute = substituteInfo.split("$");
    for (let j = 0; j < arrSubstitute.length; j++) {
        if (arrSubstitute.length > 1) {
            tmpArr = arrSubstitute[j].split("|");
            arrDepNm[j] = tmpArr[0];
            arrEmpNm[j] = tmpArr[1];
            arrTelNo[j] = tmpArr[2];
        } else {
            tmpArr = arrSubstitute[j].split("|");
            arrDepNm = tmpArr[0];
            arrEmpNm = tmpArr[1];
            arrTelNo = tmpArr[2];
        }
    }
    if (arrSubstitute.length > 1) {
        for (let n = 0; n < arrSubstitute.length; n++) {
            scwin.substituteTable += "		&lt;tr&gt;";
            scwin.substituteTable += "			&lt;td class&#061;&quot;td_board&quot;&gt;" + arrDepNm[n] + "&lt;&#47;td&gt;";
            scwin.substituteTable += "			&lt;td class&#061;&quot;td_board&quot;&gt;" + arrEmpNm[n] + "&lt;&#47;td&gt;";
            scwin.substituteTable += "			&lt;td class&#061;&quot;td_board&quot;&gt;" + arrTelNo[n] + "&lt;&#47;td&gt;";
            scwin.substituteTable += "		&lt;&#47;tr&gt;";
        }
    } else {
        scwin.substituteTable += "		&lt;tr&gt;";
        scwin.substituteTable += "			&lt;td class&#061;&quot;td_board&quot;&gt;" + arrDepNm + "&lt;&#47;td&gt;";
        scwin.substituteTable += "			&lt;td class&#061;&quot;td_board&quot;&gt;" + arrEmpNm + "&lt;&#47;td&gt;";
        scwin.substituteTable += "			&lt;td class&#061;&quot;td_board&quot;&gt;" + arrTelNo + "&lt;&#47;td&gt;";
        scwin.substituteTable += "		&lt;&#47;tr&gt;";
    }
    scwin.substituteTable += "	&lt;&#47;table&gt;";
    const popName2 = "pop_substituete";
    if (scwin.getCookie(popName2) !== popName2) {
